use crate::stage14::{DdrSequenceError,DdrTrainer};use crate::stage15::{EarlyDdrReport,EarlyDdrRuntime};
pub trait DdrEntryHooks{type Error;fn preflight(&mut self)->Result<(),Self::Error>;fn timer_already_ready(&mut self)->bool;fn emit_banner(&mut self);fn post_training_check(&mut self)->Result<(),Self::Error>;fn emit_error(&mut self);fn invalidate_icache_all(&mut self);}
#[derive(Clone,Copy,Debug,PartialEq,Eq)]pub struct DdrInitEntryReport{pub early:EarlyDdrReport,pub timer_reinitialized:bool}
#[derive(Clone,Copy,Debug,PartialEq,Eq)]pub enum DdrInitEntryError<HE,TE>{Hook(HE),Training(TE)}
pub fn run_ddr_init_entry_flow<I:EarlyDdrRuntime,T:DdrTrainer,H:DdrEntryHooks>(io:&mut I,trainer:&mut T,hooks:&mut H,uart_base:u64,baud:u32)->Result<DdrInitEntryReport,DdrInitEntryError<H::Error,T::Error>>{if let Err(e)=hooks.preflight(){hooks.emit_error();hooks.invalidate_icache_all();return Err(DdrInitEntryError::Hook(e))}let timer_reinitialized=!hooks.timer_already_ready();if timer_reinitialized{crate::stage13::init_arch_timer(io)}crate::stage12::init_debug_uart(io,uart_base,baud);hooks.emit_banner();let probe_byte=match crate::stage14::run_ddr_probe_and_train(io,trainer){Ok(v)=>v,Err(DdrSequenceError::Training(e))=>{hooks.emit_error();hooks.invalidate_icache_all();return Err(DdrInitEntryError::Training(e))}};if let Err(e)=hooks.post_training_check(){hooks.emit_error();hooks.invalidate_icache_all();return Err(DdrInitEntryError::Hook(e))}hooks.invalidate_icache_all();Ok(DdrInitEntryReport{early:EarlyDdrReport{probe_byte,uart_base,baud},timer_reinitialized})}
#[cfg(test)]mod tests{use super::*;use rk3588_boot_support::{BarrierOps,DelayUs,Mmio32,Mmio8};use crate::stage13::ArchTimerIo;struct I{freq:u32,status:u32,probe:u8}impl Mmio32 for I{fn read32(&mut self,a:u64)->u32{if a==crate::stage14::DDR_PROBE_BASE+0x84{self.status}else{0}}fn write32(&mut self,a:u64,v:u32){if a==crate::stage14::DDR_PROBE_BASE+0x84&&v==15{self.status=3}}}impl Mmio8 for I{fn read8(&mut self,a:u64)->u8{if a==crate::stage14::DDR_PROBE_BASE+0x22{self.probe}else{0}}}impl DelayUs for I{fn delay_us(&mut self,_:u32){}}impl BarrierOps for I{fn dsb(&mut self){}fn isb(&mut self){}}impl ArchTimerIo for I{fn write_cntfrq_el0(&mut self,h:u32){self.freq=h}}impl crate::stage12::DebugUartIo for I{fn write32(&mut self,_:u64,_:u32){}}struct T(u8);impl DdrTrainer for T{type Error=();fn train(&mut self,p:u8)->Result<(),()>{self.0=p;Ok(())}}struct H(u8);impl DdrEntryHooks for H{type Error=();fn preflight(&mut self)->Result<(),()>{Ok(())}fn timer_already_ready(&mut self)->bool{false}fn emit_banner(&mut self){}fn post_training_check(&mut self)->Result<(),()>{Ok(())}fn emit_error(&mut self){}fn invalidate_icache_all(&mut self){self.0+=1}}#[test]fn entry(){let mut i=I{freq:0,status:0,probe:0x5a};let mut t=T(0);let mut h=H(0);let r=run_ddr_init_entry_flow(&mut i,&mut t,&mut h,0xFE66_0000,115200).unwrap();assert_eq!(r.early.probe_byte,0x5a);assert!(r.timer_reinitialized);assert_eq!(i.freq,24_000_000);assert_eq!(h.0,1);}}
